* Driving source with DC common-mode and AC/Pulse excitations
Vin_src vin 0 dc 0.7 ac 1 pulse(0.5 0.9 100n 1n 1n 200n 500n)

* Feedback network for Open-Loop AC (Baker Fig 24.25 setup: DC closed loop, AC open loop)
* When doing transient step response, Rfb provides unity follower feedback
* For open-loop AC analysis, Cfb grounds the inverting terminal to isolate AC

.control
* 1. Operating Point Analysis
op
let power = -i(VDD) * 1.8
print power

* 2. Open-Loop AC Analysis
ac dec 50 10 1G
let aol_db = vdb(vout)
let phase = 180/PI * cph(v(vout))

meas ac aol_dc find aol_db at=10
meas ac fun when aol_db=0 fall=1
meas ac phase_at_fun find phase when aol_db=0 fall=1
let pm = phase_at_fun + 180
print pm
meas ac gain_at_180 find aol_db when phase=-180 fall=1
let gm = -gain_at_180
print gm

* 3. Transient Step Response (500 mV to 900 mV)
tran 0.5n 600n
meas tran v_init find v(vout) at=90n
meas tran v_peak max v(vout) from=100n to=300n
meas tran sr_pos trig v(vout) val=0.55 rise=1 targ v(vout) val=0.85 rise=1
meas tran sr_neg trig v(vout) val=0.85 fall=1 targ v(vout) val=0.55 fall=1
let sr_p = (0.85 - 0.55) / (sr_pos * 1e6)
let sr_n = (0.85 - 0.55) / (sr_neg * 1e6)
print sr_p sr_n

quit
.endc
.end

